CREATE TABLE IF NOT EXISTS company_devices(id uuid PRIMARY KEY, name text NOT NULL, token_hash text NOT NULL, generation uuid NOT NULL, capabilities jsonb NOT NULL DEFAULT '{}', last_seen timestamptz, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS company_device_tasks(id uuid PRIMARY KEY, device_id uuid NOT NULL REFERENCES company_devices(id), generation uuid NOT NULL, action text NOT NULL, input jsonb NOT NULL, state text NOT NULL CHECK(state IN ('queued','claimed','completed','failed','expired')), claim_hash text, output jsonb, deadline timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS company_device_tasks_queue ON company_device_tasks(device_id,state,created_at);

